const payload = $input.item.json || {};
const error = payload.error || {};
const execution = payload.execution || {};
const workflow = payload.workflow || {};
const n8nDetails = payload.n8nDetails || error.n8nDetails || {};

// helpers
const pickFirst = (...vals) => vals.find(v => v !== undefined && v !== null && String(v).trim() !== '');
const toStr = (v) => (v === undefined || v === null) ? '' : (typeof v === 'string' ? v : JSON.stringify(v));
const clip = (s, max = 2000) => {
  const str = toStr(s);
  return str.length > max ? (str.slice(0, max) + '…[recortado]') : str;
};

// Fecha
const errorDate = new Date().toLocaleString('es-ES', {
  timeZone: 'Europe/Madrid',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit'
});

// IDs / names
const workflowName = pickFirst(workflow.name, payload.workflowName, 'Desconocido');
const workflowId = pickFirst(workflow.id, payload.workflowId, 'N/A');
const executionId = pickFirst(execution.id, payload.executionId, 'N/A');
const executionMode = pickFirst(execution.mode, payload.executionMode, 'N/A');

// Nodo fallido (fallbacks)
const failedNode =
  pickFirst(
    error?.node?.name,
    error?.nodeName,
    error?.context?.nodeName,
    error?.cause?.node?.name,
    error?.cause?.nodeName,
    n8nDetails?.nodeName,
    'Desconocido'
  );

// Mensaje (fallbacks)
const errorMessage =
  pickFirst(
    error?.message,
    error?.cause?.message,
    error?.description,
    payload?.errorMessage,
    payload?.errorDescription,
    payload?.errorDetails?.rawErrorMessage?.[0],
    error?.errorDetails?.rawErrorMessage?.[0],
    n8nDetails?.stackTrace?.[0],
    'Sin mensaje de error'
  );

const errorDescription =
  pickFirst(
    error?.description,
    payload?.errorDescription,
    ''
  );

// Tipo / código HTTP si existe
const httpCode =
  pickFirst(
    payload?.errorDetails?.httpCode,
    error?.errorDetails?.httpCode,
    n8nDetails?.httpCode,
    ''
  );

const errorType =
  pickFirst(
    error?.name,
    payload?.name,
    (n8nDetails?.stackTrace?.[0] || '').split(':')[0],
    ''
  );

// Stack recortado
const errorStack =
  clip(
    pickFirst(
      error?.stack,
      error?.cause?.stack,
      n8nDetails?.stackTrace ? n8nDetails.stackTrace.join('\n') : ''
    ),
    4000
  );

// Dump recortado (para que nunca venga vacío)
const rawDump = clip(error, 4000);

// URL ejecución (UI)
const n8nUrl = 'https://n8n.finanzia2.com';
const executionUrl = `${n8nUrl}/executions/${executionId}`;

return {
  json: {
    errorDate,
    workflowName,
    workflowId,
    executionId,
    executionMode,
    failedNode,
    errorType,
    httpCode,
    errorMessage,
    errorDescription,
    errorStack,
    executionUrl,
    rawDump
  }
};
